PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://trivyn.io/ontologies/moose#>
SELECT ?constraint ?title ?status WHERE {
  ?constraint a moose:Constraint ;
              rdfs:label ?title ;
              moose:status ?status .
  FILTER(LCASE(STR(?status)) = "accepted")
}
ORDER BY ?title

